    aw_s->controlBposBR = controlBposBR;
    aw_s->controlBnegBR = controlBnegBR;
    aw_s->targetposBR = targetposBR;
    aw_s->targetnegBR = targetnegBR;
    aw_s->controlAposCR = controlAposCR;
    aw_s->controlAnegCR = controlAnegCR;
    aw_s->controlBposCR = controlBposCR;
    aw_s->controlBnegCR = controlBnegCR;
    aw_s->targetnegCR = targetnegCR;
