    aw_Logical4_fast_t *aw_s = (aw_Logical4_fast_t *)aw_state;
    const double aw_sample_rate = aw_s->aw_sample_rate;
    (void)aw_sample_rate;
    double controlAposL = aw_s->controlAposL;
